def _worker_identifier(sender: object, kwargs: dict) -> str | None:
    hostname = getattr(sender, "hostname", None)
    if isinstance(hostname, str) and hostname:
        return hostname

    if isinstance(sender, str) and sender:
        return sender

    for key in ("hostname", "nodename"):
        value = kwargs.get(key)
        if isinstance(value, str) and value:
            return value

    instance = kwargs.get("instance")
    instance_hostname = getattr(instance, "hostname", None)
    if isinstance(instance_hostname, str) and instance_hostname:
        return instance_hostname

    return None


@worker_ready.connect
def on_worker_ready(sender=None, **kwargs):
    configure_logging(
        log_level=settings.APP_LOG_LEVEL,
        json_logs=settings.is_production,
    )
    worker_id = _worker_identifier(sender, kwargs)
    if worker_id:
        logger.info("Celery worker ready", hostname=worker_id)
    else:
        logger.info("Celery worker ready")


@worker_shutting_down.connect
def on_worker_shutting_down(sender=None, sig=None, how=None, exitcode=None, **kwargs):
    worker_id = _worker_identifier(sender, kwargs)
    log_kwargs = {}
    if worker_id:
        log_kwargs["hostname"] = worker_id
    if sig is not None:
        log_kwargs["signal"] = str(sig)
    if how is not None:
        log_kwargs["shutdown_method"] = str(how)
    if exitcode is not None:
        log_kwargs["exitcode"] = exitcode
    logger.info("Celery worker shutting down", **log_kwargs)
